def integrate(f, a, b, n=10000):
    h = (b - a) / n
    return h * (0.5 * (f(a) + f(b)) + sum(f(a + i * h) for i in range(1, n)))
print(round(integrate(lambda t: 2 * t, 0, 5), 2))
